WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/24.0/connection.js")} 
try{ 
if('{!Proposal__c.Active__c}' == 1){ 
var conf = confirm('Please ensure that you’ve synced or uploaded the customer approval email with this proposal'); 
if(conf == true){ 
var proposal = new sforce.SObject("Proposal__c"); 
proposal.id = '{!Proposal__c.Id}'; 
proposal.status__c = 'Accepted by Customer'; 
var result = sforce.connection.update([proposal]); 
window.location.reload(); 
} 
}else if('{!Proposal__c.Active__c}' == 0){ 
alert('Proposal should be Active!'); 
} 
}catch(e){ 
alert('An Error has Occured. Error:' +e); 
}
